//! The Job's head: its title, state, marks and the acts on it.

use gpui::{div, prelude::*, Context, SharedString, Window};

use super::JobView;
use crate::token;

impl JobView {
    /// The title band over the thread, with the state glyph at its start.
    pub(super) fn render_head(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let title = self.title(cx).unwrap_or_else(|| SharedString::from("Untitled Job"));
        div()
            .flex()
            .items_center()
            .gap(token::SPACE_2)
            .px(token::SPACE_4)
            .child(self.state_glyph(cx))
            .child(div().text_size(token::TEXT_LG).child(title))
            .child(self.marks(window, cx))
    }
}

import { describe, expect, it } from "vitest";

import { readSettings } from "./settings";

describe("links", () => {
  it("opens pull requests in Armada on a fresh machine", () => {
    expect(readSettings({}).links.openPullRequestsIn).toBe("armada");
  });
});

//! The routes the api serves.

use axum::{routing::get, Router};

use crate::{audit_table, settings_page, webhook_queue};

/// Every route, under its path.
pub fn router() -> Router {
    Router::new()
        .route("/audit", get(audit_table::page))
        .route("/settings", get(settings_page::page))
        .route("/webhooks", get(webhook_queue::drain))
}
